test('search returns true for inserted word', () => {
  const t = new Trie();
  t.insert('hello');
  expect(t.search('hello')).toBe(true);
});

test('search returns false for non-inserted word', () => {
  const t = new Trie();
  t.insert('hello');
  expect(t.search('hell')).toBe(false);
  expect(t.search('world')).toBe(false);
});

test('startsWith returns all matching words', () => {
  const t = new Trie();
  ['cat','car','card','care','dog'].forEach(w => t.insert(w));
  const result = t.startsWith('car').sort();
  expect(result).toEqual(['car','card','care']);
});

test('startsWith returns empty array for no matches', () => {
  const t = new Trie();
  t.insert('hello');
  expect(t.startsWith('xyz')).toEqual([]);
});

