test('search distinguishes prefix from full word', () => {
  const t = new Trie();
  t.insert('app');
  t.insert('apple');
  expect(t.search('app')).toBe(true);
  expect(t.search('appl')).toBe(false);
  expect(t.search('apple')).toBe(true);
});

solution:
export class Trie {
  constructor() {
    this.root = { children: {}, isEnd: false };
  }

  insert(word) {
    let node = this.root;
    for (const ch of word) {
      if (!node.children[ch]) node.children[ch] = { children: {}, isEnd: false };
      node = node.children[ch];
    }
    node.isEnd = true;
  }

  search(word) {
    let node = this.root;
    for (const ch of word) {
      if (!node.children[ch]) return false;
      node = node.children[ch];
    }
    return node.isEnd;
  }

  startsWith(prefix) {
    let node = this.root;
    for (const ch of prefix) {
      if (!node.children[ch]) return [];
      node = node.children[ch];
    }
    const results = [];
    const dfs = (n, word) => {
      if (n.isEnd) results.push(word);
      for (const [ch, child] of Object.entries(n.children)) dfs(child, word + ch);
    };
    dfs(node, prefix);
    return results;
  }
}
